1	import { expect, test } from "../../fixtures/test.ts";
2	import { type AddressFields } from "../../pages/addressDialog.ts";
3	import { DraftOrderPage } from "../../pages/draftOrderPage.ts";
4	import { CHANNEL, CUSTOMER, ORDERS_SCENARIO, PRODUCTS } from "../../scenarios/orders.ts";
5	
6	/**
7	 * Staff taking an order by hand: a draft, a line, a customer, a shipping method, finalized
8	 * into an order. Replaces legacy SALEOR_28, 76 and 84 - one flow reached from two lists -
9	 * and SALEOR_217.
10	 *
11	 * Each test is one story with a step per stage, so a failure names the stage it broke in.
12	 */
13	test.use({ scenario: ORDERS_SCENARIO });
14	
15	test("Staff creates an order for an existing customer and finalizes it #e2e", async ({ page }) => {
16	  // Arrange
17	  const draft = new DraftOrderPage(page);
