270	    const end = { x: start.x, y: start.y + 20 };
271	
272	    await this.dispatchPrimaryPointer(locator, "pointerdown", start);
273	    await this.dispatchPrimaryPointer(locator, "pointermove", end);
274	    await this.dispatchPrimaryPointer(locator, "pointerup", end);
